import AppKit

/// Recent copied text, kept in memory only. It watches the general pasteboard's
/// change count while enabled and skips items that apps mark as concealed,
/// transient or auto-generated (for example, passwords from a password manager).
@MainActor
final class ClipboardHistory: ObservableObject {
    struct Item: Identifiable, Equatable {
        let id = UUID()
        let text: String
        let date: Date
    }

    static let limit = 20
    private static let characterLimit = 10_000
    private static let skippedTypes: Set<NSPasteboard.PasteboardType> = [
        .init("org.nspasteboard.ConcealedType"), .init("org.nspasteboard.TransientType"),
        .init("org.nspasteboard.AutoGeneratedType"), .init("com.agilebits.onepassword")
    ]

    @Published private(set) var items: [Item] = []
    private var timer: Timer?
    private var lastChangeCount = NSPasteboard.general.changeCount

    var isWatching: Bool { timer != nil }

    func setEnabled(_ enabled: Bool) {
        if enabled {
            guard timer == nil else { return }
            // Only changes after enabling are recorded; the current clipboard is not read.
            lastChangeCount = NSPasteboard.general.changeCount
            let timer = Timer(timeInterval: 0.75, repeats: true) { [weak self] _ in
                MainActor.assumeIsolated { self?.poll() }
            }
            timer.tolerance = 0.25
            RunLoop.main.add(timer, forMode: .common)
            self.timer = timer
        } else {
            timer?.invalidate()
            timer = nil
            items.removeAll()
        }
    }

    func clear() { items.removeAll() }

    func remove(_ id: UUID) { items.removeAll { $0.id == id } }

    /// Copies an item back to the clipboard and moves it to the top.
    func copy(_ item: Item) {
        let pasteboard = NSPasteboard.general
        pasteboard.clearContents()
        pasteboard.setString(item.text, forType: .string)
        lastChangeCount = pasteboard.changeCount
        items.removeAll { $0.id == item.id }
        items.insert(Item(text: item.text, date: Date()), at: 0)
    }

    private func poll() {
        let pasteboard = NSPasteboard.general
        guard pasteboard.changeCount != lastChangeCount else { return }
        lastChangeCount = pasteboard.changeCount
        let types = Set(pasteboard.types ?? [])
        guard types.isDisjoint(with: Self.skippedTypes), let text = pasteboard.string(forType: .string) else { return }
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return }
        let bounded = String(text.prefix(Self.characterLimit))
        items.removeAll { $0.text == bounded }
        items.insert(Item(text: bounded, date: Date()), at: 0)
        if items.count > Self.limit { items.removeLast(items.count - Self.limit) }
    }
}
